"use client";

import { type InputHTMLAttributes, type KeyboardEvent, useCallback, useEffect, useRef, useState } from "react";
import { clamp } from "../utils/motion";
import { cx } from "../utils/cx";
import { MinusIcon, PlusIcon } from "../icons/interface";

export type NumberInputProps = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "defaultValue" | "onChange" | "type" | "min" | "max" | "step" | "role"
> & {
  /** Names the field (required unless a visible label is attached with `id`). */
  "aria-label"?: string;
  value?: number | null;
  defaultValue?: number | null;
  onValueChange?: (value: number | null) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Format the shown value (default: plain, trimmed to the step's decimals). */
  format?: (value: number) => string;
};

const decimals = (n: number) => (String(n).split(".")[1] ?? "").length;

/**
 * A numeric field with minus and plus buttons. Arrow keys and Page keys step it, Home and End jump to the limits,
 * holding a button repeats, and typed text is parsed and clamped when you leave the field.
 */
export function NumberInput({
  value: controlled,
  defaultValue = null,
  onValueChange,
  min = Number.NEGATIVE_INFINITY,
  max = Number.POSITIVE_INFINITY,
  step = 1,
  format,
  disabled,
  className,
  onBlur,
  onKeyDown,
  ...rest
}: NumberInputProps) {
  const places = decimals(step);
  const show = useCallback(
    (v: number | null) => (v === null ? "" : format ? format(v) : v.toFixed(places)),
    [format, places],
  );
  const [inner, setInner] = useState<number | null>(defaultValue);
  const value = controlled === undefined ? inner : controlled;
  const [text, setText] = useState(show(value));
  const editing = useRef(false);
  useEffect(() => {
    if (!editing.current) setText(show(value));
  }, [value, show]);

  const latest = useRef(value);
  latest.current = value;
  const set = useCallback(
    (next: number | null) => {
      const n = next === null ? null : Number(clamp(next, min, max).toFixed(places));
      if (controlled === undefined) setInner(n);
      onValueChange?.(n);
      latest.current = n;
      setText(show(n));
    },
    [controlled, min, max, places, onValueChange, show],
  );
  const bump = useCallback(
    (dir: 1 | -1, mult = 1) =>
      set((latest.current ?? (dir > 0 ? Math.max(min, 0) - step : Math.min(max, 0) + step)) + dir * step * mult),
    [set, step, min, max],
  );

  const hold = useRef<{ t?: ReturnType<typeof setTimeout>; i?: ReturnType<typeof setInterval> }>({});
  const stop = useCallback(() => {
    clearTimeout(hold.current.t);
    clearInterval(hold.current.i);
  }, []);
  useEffect(() => stop, [stop]);
  const press = (dir: 1 | -1) => ({
    onPointerDown: (e: React.PointerEvent) => {
      if (disabled || e.button !== 0) return;
      bump(dir);
      hold.current.t = setTimeout(() => {
        hold.current.i = setInterval(() => bump(dir), 70);
      }, 420);
    },
    onPointerUp: stop,
    onPointerLeave: stop,
    onPointerCancel: stop,
  });

  const commit = () => {
    editing.current = false;
    const parsed = Number.parseFloat(text.replace(/,/g, ""));
    if (text.trim() === "") set(null);
    else if (Number.isFinite(parsed)) set(parsed);
    else setText(show(value));
  };
  const key = (e: KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented || disabled) return;
    if (e.key === "ArrowUp") bump(1);
    else if (e.key === "ArrowDown") bump(-1);
    else if (e.key === "PageUp") bump(1, 10);
    else if (e.key === "PageDown") bump(-1, 10);
    else if (e.key === "Home" && Number.isFinite(min)) set(min);
    else if (e.key === "End" && Number.isFinite(max)) set(max);
    else if (e.key === "Enter") {
      commit();
      return;
    } else return;
    e.preventDefault();
  };
  const atMin = value !== null && value <= min;
  const atMax = value !== null && value >= max;
  return (
    <div className={cx("hm-number hm-control", className)} data-disabled={disabled ? "" : undefined}>
      <button
        type="button"
        className="hm-number-button"
        tabIndex={-1}
        aria-label="Decrease"
        disabled={disabled || atMin}
        {...press(-1)}
      >
        <MinusIcon size={12} strokeWidth={1.6} />
      </button>
      <input
        {...rest}
        type="text"
        role="spinbutton"
        inputMode="decimal"
        autoComplete="off"
        disabled={disabled}
        aria-valuenow={value ?? undefined}
        aria-valuemin={Number.isFinite(min) ? min : undefined}
        aria-valuemax={Number.isFinite(max) ? max : undefined}
        value={text}
        className="hm-number-input"
        onFocus={() => {
          editing.current = true;
        }}
        onChange={(e) => setText(e.target.value)}
        onBlur={(e) => {
          onBlur?.(e);
          commit();
        }}
        onKeyDown={key}
      />
      <button
        type="button"
        className="hm-number-button"
        tabIndex={-1}
        aria-label="Increase"
        disabled={disabled || atMax}
        {...press(1)}
      >
        <PlusIcon size={12} strokeWidth={1.6} />
      </button>
    </div>
  );
}
